SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"01a00459-8de2-79fc-b442-a88cd6ce2f45","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Benjamin and Daniel have monthly allowances in the ratio 7 : 4. After each of them spends $50, the ratio of their remaining allowances becomes 5 : 2. Calculate Daniel''s allowance at the start.","model_answer":"$100","explanation":"Let Benjamin''s initial allowance be 7x and Daniel''s initial allowance be 4x. After spending $50 each, their remaining allowances are 7x - 50 and 4x - 50. Set up ratio: (7x - 50) / (4x - 50) = 5 / 2. Cross-multiply: 2(7x - 50) = 5(4x - 50) => 14x - 100 = 20x - 250 => 6x = 150 => x = 25. Daniel''s allowance = 4 * 25 = $100.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:13.026Z","updated_at":"2026-08-15T07:36:13.026Z"},{"id":"01a00459-8de7-7fc8-a4cc-433f7eecc779","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Given that 1 / (3^(k + 2)) = 3^4 + 3^4 + 3^4, find the value of k.","model_answer":"-7","explanation":"Simplify RHS: 3^4 + 3^4 + 3^4 = 3 * (3^4) = 3^5. Rewrite LHS using negative index: 1 / (3^(k + 2)) = 3^(-(k + 2)). Equating exponents: -(k + 2) = 5 => -k - 2 = 5 => -k = 7 => k = -7.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:13.031Z","updated_at":"2026-08-15T07:36:13.031Z"},{"id":"01a00466-c83d-7730-85f3-8f230ac0d1fa","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Calculate √((15.2²)/(1 - 0.046)), giving your answer correct to the nearest whole number.","model_answer":"16","explanation":"Evaluate √((15.2²)/(0.954)) = 15.56... Therefore, the answer to the nearest whole number is 16.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:39.931Z","updated_at":"2026-08-15T07:50:39.931Z"},{"id":"01a00466-c84e-7730-b6f3-4e8b47ddcba5","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify 4x - 7(x - 2).","model_answer":"14 - 3x","explanation":"4x - 7(x - 2) = 4x - 7x + 14 = 14 - 3x.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:39.950Z","updated_at":"2026-08-15T07:50:39.950Z"},{"id":"01a00466-c868-7374-a22f-9dbc4041ab71","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify (18a²b⁴) ÷ (6ab⁻²), leaving your answer with positive indices.","model_answer":"3ab⁶","explanation":"(18a²b⁴)/(6ab⁻²) = 3a^(2-1)b^(4-(-2)) = 3ab⁶.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:39.976Z","updated_at":"2026-08-15T07:50:39.976Z"},{"id":"01a00466-c877-7805-8381-a6648746bdb1","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A car travels an average of 0.082 kilometres per litre of fuel. Find its fuel consumption in litres per kilometre, correct to three significant figures.","model_answer":"12.2 litres per kilometre","explanation":"Litres per kilometre = 1 ÷ 0.082 = 12.195..., which is 12.2 litres per kilometre to three significant figures.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:39.991Z","updated_at":"2026-08-15T07:50:39.991Z"},{"id":"01a00466-c888-780d-8a37-ac9d34d7d95d","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 0.000736 in standard form.","model_answer":"7.36 × 10⁻⁴","explanation":"Move the decimal point four places to the right: 0.000736 = 7.36 × 10⁻⁴.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.008Z","updated_at":"2026-08-15T07:50:40.008Z"},{"id":"01a00466-c899-730e-9715-0fd9006900ce","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"Convert 0.00425 m³ into cm³.","model_answer":"4250 cm³","explanation":"Since 1 m³ = 1,000,000 cm³, 0.00425 m³ = 0.00425 × 1,000,000 = 4250 cm³.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.025Z","updated_at":"2026-08-15T07:50:40.025Z"},{"id":"01a00466-c8ad-75d4-975b-4ffb2d5f4e49","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","prompt":"Solve x/8 - (3x - 2)/5 = 2.","model_answer":"x = -64/19","explanation":"Multiply by 40: 5x - 8(3x - 2) = 80. Hence, 5x - 24x + 16 = 80, so -19x = 64 and x = -64/19.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.045Z","updated_at":"2026-08-15T07:50:40.045Z"},{"id":"01a00466-c8b8-7337-9546-9dd3c5332c75","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"A rectangular prism is made using 432 unit cubes. Its square base has side length greater than 3 units. Find the smallest possible height of the prism.","model_answer":"3 units","explanation":"If the square base side is s, then s²h = 432. Possible square factors of 432 with s > 3 are 16 (s=4, h=27), 36 (s=6, h=12), and 144 (s=12, h=3). The largest base area 144 yields the smallest height of 3 units.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.056Z","updated_at":"2026-08-15T07:50:40.056Z"},{"id":"01a00466-c8d5-7640-8b59-e05d2de930e3","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A laptop has a marked price of $m and is sold at a discount of d%. Express its selling price as a single fraction in terms of m and d.","model_answer":"m(100 - d)/100","explanation":"The discount is md/100. Selling price = m - md/100 = m(100 - d)/100.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.085Z","updated_at":"2026-08-15T07:50:40.085Z"},{"id":"01a00466-c8e9-7526-a202-f1e78caca88b","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shop sells an item at the discounted price m(100 - d)/100 and makes a profit of 25%. Express the cost price as a single fraction in terms of m and d.","model_answer":"4m(100 - d)/500","explanation":"Selling price = 1.25 × cost price. Therefore, cost price = [m(100 - d)/100] ÷ 1.25 = 4m(100 - d)/500.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.105Z","updated_at":"2026-08-15T07:50:40.105Z"},{"id":"01a00466-c8f3-7aaf-aa86-7fce1777f966","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A bar chart compares monthly sales, but its vertical axis begins at $1500 instead of $0. Explain how this could mislead readers.","model_answer":"It exaggerates visible bar differences, making small variations appear much larger.","explanation":"Starting the vertical axis above zero removes the baseline and exaggerates the visible heights of the bars. Readers may therefore overestimate the differences between months.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.115Z","updated_at":"2026-08-15T07:50:40.115Z"},{"id":"01a00466-c911-7720-9bd3-e464de4c4e5e","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 360 as a product of its prime factors.","model_answer":"2³ × 3² × 5","explanation":"360 = 36 × 10 = (2² × 3²)(2 × 5) = 2³ × 3² × 5.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.145Z","updated_at":"2026-08-15T07:50:40.145Z"},{"id":"01a00466-c91b-7e98-af40-d3a0a6c9daf3","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Two integers have HCF 18 and LCM 360. Both integers are greater than 40. Find the two integers.","model_answer":"72 and 90","explanation":"Let the numbers be 18a and 18b, where a and b are coprime. Since their product is HCF × LCM = 18 × 360, ab = 20. The coprime factor pair giving numbers > 40 is a = 4 and b = 5, giving 72 and 90.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:50:40.155Z","updated_at":"2026-08-15T07:50:40.155Z"}]'::json)
